import 'package:flutter/material.dart';
import 'package:legacy_gantt_chart/legacy_gantt_chart.dart';

void main() => runApp(const MyApp());

class MyApp extends StatelessWidget {
  const MyApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
        home: Scaffold(
          appBar: AppBar(title: const Text('Gantt Demo')),
          body: LegacyGanttChartWidget(
            controller: LegacyGanttController(
              tasks: [
                GanttTask(id: '1', title: 'Design', start: DateTime.now(), end: DateTime.now().add(const Duration(days: 5))),
                GanttTask(id: '2', title: 'Development', start: DateTime.now().add(const Duration(days: 5)), end: DateTime.now().add(const Duration(days: 15))),
              ],
            ),
          ),
        ),
      );
}
